		Set @SQL = 'CREATE FUNCTION [' + @CodePrefix + 'Architecture].[FormatDate] (@NewDate varchar(50)) RETURNS varchar(11)' + char(13) + 'AS' + char(13) + '	BEGIN' + char(13) + '		Declare @BMWFirstDash tinyint' + char(13) + '		Declare @BMWSecondDash tinyint' + char(13) + '		SET @NewDate = REPLACE(@NewDate , ''--'' , ''-0'');' + char(13) + '		set @BMWFirstDash = CHARINDEX(''-'',@NewDate,0);' + char(13) + '		set @BMWSecondDash = CHARINDEX(''-'',@NewDate,@BMWFirstDash + 1);' + char(13) + '		IF(@BMWFirstDash = 4 And @BMWSecondDash = 7)' + char(13) + '		BEGIN' + char(13) + '			-- print (''Jan-02-2020'');				' + char(13) + '			SET @NewDate = SUBSTRING(@NewDate,5,2) + ''-'' + SUBSTRING(@NewDate,1,3) + ''-'' + RIGHT(@NewDate,4);' + char(13) + '		END' + char(13) + '		IF(@BMWFirstDash = 5 And @BMWSecondDash = 9)' + char(13) + '		BEGIN				' + char(13) + '			-- print (''2020-Jan-02'');' + char(13) + '			SET @NewDate =  RIGHT(@NewDate,2) + ''-'' +SUBSTRING(@NewDate,6,3) + ''-'' + left(@NewDate,4) ;' + char(13) + '		END' + char(13) + '		IF(@BMWFirstDash = 5 And @BMWSecondDash = 8)' + char(13) + '		BEGIN				' + char(13) + '			-- print (''2020-02-Jan'');' + char(13) + '			SET @NewDate =  SUBSTRING(@NewDate,6,2) + ''-'' + RIGHT(@NewDate,3) + ''-'' + left(@NewDate,4) ;' + char(13) + '		END' + char(13) + '		IF(@BMWFirstDash = 3 And @BMWSecondDash = 8)' + char(13) + '		BEGIN				' + char(13) + '			-- print (''02-2020-Jan'');' + char(13) + '			SET @NewDate =  left(@NewDate,2) + ''-'' + RIGHT(@NewDate,3) + ''-'' + SUBSTRING(@NewDate,4,4) ;' + char(13) + '		END' + char(13) + '		return @NewDate ;' + char(13) + '	END'; Exec (@SQL);IF(@CorePrint =1) Begin print (@SQL); END;
