BusinessTransactionStarted=0; EXEC [' + @CodePrefix + 'Architecture].[ExecuteMessage] ''Update'',''5051'',@' + @CodePrefix + 'Email; RETURN;' + char(13) + '  END;' + char(13) + '  IF (@' + @CodePrefix + 'TransValue=3)' + char(13) + '  BEGIN' + char(13) + '   UPDATE [' + @CodePrefix + 'Configuration].[TechMail] SET [IsTechMailDeleted]=@' + @CodePrefix + 'IsTechMailDeleted,[UpdatedBy]=@' + @CodePrefix + 'TransUserID,[UpdatedDate]=GETDATE() WHERE [TechMailId]=@' + @CodePrefix + 'TechMailId;' + char(13) + '   COMMIT TRANSACTION; SET @BusinessTransactionStarted=0; EXEC [' + @CodePrefix + 'Architecture].[ExecuteMessage] ''Delete'',''5052'',@' + @CodePrefix + 'Email; RETURN;' + char(13) + '  END;' + char(13) + '  IF (@' + @CodePrefix + 'TransValue=4)' + char(13) + '  BEGIN' + char(13) + '   SELECT [TechMailId],[MailType],[Email],[IsTechMailActive],[IsTechMailDeleted],[AddB].[UserName] AS [AUser],FORMAT([Main].[AddedDate],''dd-MMM-yy hh:mm tt'') AS [ADate],[UpdB].[UserName] AS [UUser],FORMAT([Main].[UpdatedDate],''dd-MMM-yy hh:mm tt'') AS [UDate] FROM [' + @CodePrefix + 'Configuration].[TechMail] [Main] LEFT JOIN [' + @CodePrefix + 'Application].[Users] [AddB] ON [AddB].[UserID]=[Main].[AddedBy] LEFT JOIN [' + @CodePrefix + 'Application].[Users] [UpdB] ON [UpdB].[UserID]=[Main].[UpdatedBy] WHERE [Main].[TechMailId]=@' + @CodePrefix + 'TechMailId AND [Main].[IsTechMailDeleted]=''false'' ORDER BY [Main].[AddedDate] DESC;' + char(13) + '  END;' + char(13) + '  IF (@' + @CodePrefix + 'TransValue=5)' + char(13) + '  BEGIN' + char(13) + '   SELECT [TechMailId],[MailType],[Email],[IsTechMailActive],[IsTechMailDeleted],[AddB].[UserName] AS [AUser],FORMAT([Main].[AddedDate],''dd-MMM-yy hh:mm tt'') AS [ADate],[UpdB].[UserName] AS [UUser],FORMAT([Main].[UpdatedDate],''dd-MMM-yy hh:mm tt'') AS [UDate] FROM [' + @CodePrefix + 'Configuration].[TechMail] [Main] LEFT JOIN [' + @CodePrefix + 'Application].[Users] [AddB] ON [AddB].[UserID]=[Main].[AddedBy] LEFT JOIN [' + @CodePrefix + 'Application].[Users] [UpdB] ON [UpdB].[UserID]=[Main].[UpdatedBy] WHERE [Main].[IsTechMailDeleted]=''false'' ORDER BY [Main].[AddedDate] DESC;' + char(13) + '  END;' + char(13) + ' END TRY' + char(13) + ' BEGIN CATCH' + char(13) + '  IF (@BusinessTransactionStarted=1 AND XACT_STATE()<>0) ROLLBACK TRANSACTION;' + char(13) + '  INSERT INTO [' + @CodePrefix + 'Log].[SQLLog] ([DML],[ERROR_SEVERITY],[ERROR_STATE],[ERROR_PROCEDURE],[ERROR_LINE],[ERROR_MESSAGE]) SELECT @DBCommand,ERROR_SEVERITY(),ERROR_STATE(),ERROR_PROCEDURE(),ERROR_LINE(),ERROR_MESSAGE();' + char(13) + '  SELECT 206 AS [ResultID],ERROR_SEVERITY() AS [ErrorSeverity],ERROR_STATE() AS [ErrorState],ERROR_PROCEDURE() AS [ErrorProcedure],ERROR_LINE() AS [ErrorLine],ERROR_MESSAGE() AS [TransMessage];' + char(13) + ' END CATCH;' + char(13) + 'END;'; Exec (@SQL);IF(@MasterPrint=1) Begin print (REPLICATE(CHAR(9), 2) +'TechMail Procedure : ' + @SQL); End;
